#include <bits/stdc++.h>
using namespace std;

const int MOD1 = 1000000007;
const int MOD2 = 998244353;
const int MAXK = 7;
const int BASE = 1000000;

long long n, order;
int answer;
int sumArr[MAXK];
vector<int> v[MAXK];

void dfs1(int x, int length) {
    order++;
    v[length].push_back(((order - x) % MOD2 + MOD2) % MOD2);
    sumArr[length] = (sumArr[length] + v[length].back()) % MOD1;
    if (length == 6) return;
    for (int i = 0; i <= 9; i++) {
        dfs1(x * 10 + i, length + 1);
    }
}

void dfs2(long long x) {
    if (x > n) return;
    if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
        long long currentOrder = order;
        for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
            int size = (int)v[i].size();
            int diff = ((currentOrder - x * mul) % MOD2 + MOD2) % MOD2;
            int pos = (int)(lower_bound(v[i].begin(), v[i].end(), MOD2 - diff) - v[i].begin());
            answer = (answer + 1LL * diff * size + sumArr[i]) % MOD1;
            answer = (answer - 1LL * MOD2 * (size - pos) % MOD1 + MOD1) % MOD1;
            order += size;
        }
        return;
    }
    order++;
    answer = (answer + ((order - x) % MOD2 + MOD2) % MOD2) % MOD1;
    for (int i = 0; i <= 9; i++) {
        dfs2(x * 10 + i);
    }
}

int main() {
    cin >> n;
    order = 0;
    dfs1(0, 0);
    for (int i = 0; i <= 6; i++) {
        sort(v[i].begin(), v[i].end());
    }
    order = 0;
    for (int i = 1; i <= 9; i++) {
        dfs2(i);
    }
    cout << answer << "\n";
    return 0;
}
